<div class="seom-panel"><div class="seom-actions"><div><h2>404 Monitor</h2><p class="description">Bulk select, export and redirect broken URLs without opening each record.</p></div><button type="button" class="button" id="seom-clear-404">Clear All Logs</button></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" id="seom-404-bulk-form"><input type="hidden" name="action" value="seom_404_bulk_delete"><?php wp_nonce_field('seom_404_bulk_delete'); ?><table class="widefat striped"><thead><tr><th><input type="checkbox" id="seom-404-check-all"></th><th>URL</th><th>Referrer</th><th>Hits</th><th>First Seen</th><th>Last Seen</th><th>Action</th></tr></thead><tbody><?php global $wpdb;$rows=$wpdb->get_results("SELECT * FROM {$wpdb->prefix}seom_404_logs ORDER BY hits DESC,last_seen DESC LIMIT 1000");foreach($rows as $r): ?><tr><td><input type="checkbox" name="ids[]" value="<?php echo (int)$r->id; ?>" class="seom-404-check"></td><td><code><?php echo esc_html($r->url); ?></code></td><td><?php echo esc_html($r->referrer); ?></td><td><?php echo (int)$r->hits; ?></td><td><?php echo esc_html($r->first_seen); ?></td><td><?php echo esc_html($r->last_seen); ?></td><td><button type="button" class="button button-small seom-delete-404" data-id="<?php echo (int)$r->id; ?>">Delete</button></td></tr><?php endforeach; ?></tbody></table><p><button class="button">Delete Selected</button> <a class="button" href="<?php echo esc_url(seom_admin_page_url('tools','import')); ?>">Import / Export</a></p></form></div>
